var t=[{title:`Mérd fel az alapterületet`,text:`Jegyezd fel a szabad padló hosszát és szélességét, amely általában kisebb, mint maga a szoba. Egy álló bicepszcsavaráshoz viszonylag kevés hely kell, egy járó kitörésnek vagy egy padlón végzett gyakorlatnak viszont szüksége lehet arra, hogy kinyújthasd a karjaidat és a lábaidat. Hagyj extra helyet a mozgó súlyok körül, és gondold végig, hogyan kezdődik és végződik a gyakorlat.`},{title:`Gondolkodj három dimenzióban`,text:`A guggoláshoz vagy az álló evezéshez oldalt is hely kell a könyöködnek és a felszerelésnek. A fekvőtámaszhoz vagy a dead bughoz akkora padlófelület kell, mint a tested hossza. A kettlebell-lendítéshez nyílt tér kell a súly előtt, mögött és körül, a fej feletti nyomásokhoz és ugrásokhoz pedig függőleges hely.`},{title:`Rejtett akadályok`,text:`Figyelj az alacsony asztalokra, a lógó lámpákra, az éles sarkokra, a fűtőtestekre, a háziállatokra, a kábelekre, a szőnyegekre és a területedre nyíló ajtókra. Ellenőrizd, hogy a padló a matrac lerakása után is csúszásmentes marad-e. Ha egy ismétlést csak épp úgy tudsz befejezni, hogy nem érsz a bútorhoz, a hely túl szűk egy teljes edzéshez.`},{title:`Terv kis terekhez`,text:`Szűk helyen helyben végzett osztott guggolást csinálj a járó kitörés helyett, és ülő vagy padlón végzett felsőtest-munkát a nagy oldalirányú mozdulatok helyett. Ha a szoba túl kicsi a terhelt hordozásokhoz, végezz anti-laterálflexiós gyakorlatokat egy helyben. Tartsd meg a mozgásmintát, és hagyd, hogy a konkrét gyakorlat változzon.`},{title:`A TrainUp használata`,text:`A Profilban add meg a padlóméretedet és a belmagasságodat. A terv ekkor csak olyan gyakorlatokat választ, amelyek mozgása, a felszereléssel együtt, belefér ebbe a térbe.`}];var l=[{label:`ACE gyakorlatkönyvtár`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: súlyzós edzés biztonsága és technikája`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`2026-os ACSM állásfoglalás`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:t,sources:l};export{s as default,t as sections,l as sources};